171: function buildShelter(){const x=player.x+Math.sin(player.yaw)*2.5,z=player.z-Math.cos(player.yaw)*2.5,y=groundY(x,z);const group=new THREE.Group();group.position.set(x,y,z);const wood=new THREE.MeshStandardMaterial({color:0x76583a,roughness:1});const leaf=new THREE.MeshStandardMaterial({color:0x45623b,roughness:1,side:THREE.DoubleSide});for(let i=0;i<5;i++){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.055,.08,3.8,5),wood);pole.position.set((i-2)*.37,1.05,0);pole.rotation.z=i<2?-.68:.68;pole.castShadow=true;group.add(pole);}const roof=new THREE.Mesh(new THREE.PlaneGeometry(3.1,3.6),leaf);roof.position.set(0,2.0,0);roof.rotation.set(-.58,0,0);roof.castShadow=true;group.add(roof);scene.add(group);}
