const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
(async()=>{
 const browser=await chromium.launch(config.browser.launchOptions);
 const page=await browser.newPage({viewport:{width:1440,height:900}});
 const errors=[];const bad=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});
 await page.route('**/src/game.js',async route=>{const response=await route.fetch();const body=await response.text();await route.fulfill({response,body:body+'\nwindow.__test={player,resources,interact,eat,craft,riverX,groundY,DAY_SECONDS,TARGET_SECONDS};'});});
 await page.goto('http://127.0.0.1:8000');
 await page.waitForFunction(()=>window.__test);
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/latest/started-desktop.png'});
 await page.locator('#start-button').click();
 const api=()=>page.evaluate(()=>({p:window.__test.player,resources:window.__test.resources.map(r=>({type:r.type,x:r.x,z:r.z,active:r.active}))}));
 await page.waitForTimeout(600);
 let result={};
 result.stationary=await page.evaluate(()=>{const p=window.__test.player;return {stamina:p.stamina,alive:p.alive}});
 await page.waitForTimeout(1700);
 result.stationaryAfter=await page.evaluate(()=>({stamina:window.__test.player.stamina,water:window.__test.player.water,food:window.__test.player.food}));
 // Add predictable resource samples by moving the player to their actual locations.
 for(const type of ['stick','stick','stick','stone','stone','berry']){
   await page.evaluate(type=>{const {player,resources}=window.__test;const r=resources.find(v=>v.type===type&&v.active);player.x=r.x;player.z=r.z;window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyE'}));},type);
 }
 result.afterGather=await page.evaluate(()=>({sticks:window.__test.player.sticks,stones:window.__test.player.stones,berries:window.__test.player.berries,weight:document.querySelector('#pack-weight').textContent}));
 await page.evaluate(()=>{const p=window.__test.player;p.food=50;p.water=40;const r=window.__test.resources.find(v=>v.type==='berry'&&v.active);p.x=r.x;p.z=r.z;window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyE'}));window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyF'}));});
 result.eat=await page.evaluate(()=>({food:window.__test.player.food,berries:window.__test.player.berries}));
 // Drink from river
 await page.evaluate(()=>{const {player,riverX}=window.__test;player.z=0;player.x=riverX(0);player.water=20;window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyE'}));});
 result.drink=await page.evaluate(()=>window.__test.player.water);
 // Exact collection counts can be set for validating crafting UI and shelter placement.
 await page.evaluate(()=>{const p=window.__test.player;p.sticks=3;p.stones=2;document.querySelector('#craft-button').click()});
 result.craft=await page.evaluate(()=>({shelter:window.__test.player.shelter,button:document.querySelector('#craft-button').textContent.trim()}));
 await page.evaluate(()=>{window.__test.player.elapsed=window.__test.TARGET_SECONDS;});
 await page.waitForFunction(()=>!document.querySelector('#end-overlay').classList.contains('hidden'));
 result.end=await page.locator('#end-title').textContent();
 result.errors=errors;result.badResponses=bad;
 console.log(JSON.stringify(result,null,2));
 await browser.close();
})();

